begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(36);

select extensions.ok((select relrowsecurity from pg_class where oid='public.sos_rounds'::regclass),'SOS rounds have RLS enabled');
select extensions.ok((select relrowsecurity from pg_class where oid='public.sos_rate_limits'::regclass),'SOS abuse-limit keys have RLS enabled');
select extensions.has_column('public','clinics','supports_24h','clinic has explicit emergency-service capability');
select extensions.has_column('public','clinics','emergency_status','clinic has live emergency status');
select extensions.has_table('public','sos_rounds','durable rounds table exists');
select extensions.has_column('public','sos_dispatches','round_id','dispatch rows belong to a round');
select extensions.ok(not exists(select 1 from pg_policy where polrelid='public.sos_requests'::regclass and polname='sos_clinic_read'),'clinic role has no direct request policy that could expose exact location/contact');
select extensions.ok(exists(select 1 from pg_policy where polrelid='public.sos_dispatches'::regclass and polname='dispatch_clinic_read'),'clinic dispatch reads are isolated by clinic membership');
select extensions.ok(position('status=''searching''' in pg_get_functiondef('public.accept_sos_v2(uuid,uuid)'::regprocedure))>0,'accept RPC atomically conditions the winner on searching status');
select extensions.ok(position('for update' in lower(pg_get_functiondef('public.accept_sos_v2(uuid,uuid)'::regprocedure)))>0,'accept RPC serializes racing accepts on the request row');
select extensions.ok((select polqual::text like '%is_clinic_member%' from pg_policy where polrelid='public.sos_dispatches'::regclass and polname='dispatch_clinic_read'),'dispatch RLS scopes reads to the addressed clinic membership');
select extensions.has_function('public','advance_sos_rounds',ARRAY['integer','integer'],'durable round advancement is callable by the service worker');
select extensions.ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='sos_dispatches_request_clinic_uq'),'a clinic can be dispatched at most once per SOS request');
select extensions.has_column('public','sos_requests','arrival_status','owner-facing clinic arrival progress is persisted');
select extensions.has_column('public','sos_requests','photo_path','SOS photo reference is stored on the request');
select extensions.has_function('public','update_sos_arrival_status',ARRAY['uuid','text'],'clinic arrival progress has a protected RPC');
select extensions.has_function('public','accepted_sos_photo',ARRAY['uuid'],'accepted clinic photo release has a protected RPC');
select extensions.ok(position('is_clinic_member' in pg_get_functiondef('public.update_sos_arrival_status(uuid,text)'::regprocedure))>0 and position('for update' in lower(pg_get_functiondef('public.update_sos_arrival_status(uuid,text)'::regprocedure)))>0,'arrival progress is clinic-authorized and serialized');
select extensions.ok(position('audit_logs' in pg_get_functiondef('public.accepted_sos_photo(uuid)'::regprocedure))>0 and position('is_clinic_member' in pg_get_functiondef('public.accepted_sos_photo(uuid)'::regprocedure))>0,'photo release checks clinic membership and writes an audit record');
select extensions.ok(exists(select 1 from storage.buckets where id='sos-private' and public=false),'SOS photos use a private bucket');
select extensions.ok(not exists(select 1 from pg_policy where polrelid='storage.objects'::regclass and (coalesce(polqual::text,'') like '%sos-private%' or coalesce(polwithcheck::text,'') like '%sos-private%')),'SOS photo objects have no direct client storage policy');
select extensions.ok(not exists(select 1 from pg_publication where pubname='supabase_realtime') or exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='sos_requests'),'owner SOS status is included in Realtime when that publication exists');
select extensions.ok(has_function_privilege('authenticated','public.update_sos_arrival_status(uuid,text)','EXECUTE'),'authenticated clinic actors can invoke the membership-checked progress RPC');
select extensions.ok(has_function_privilege('authenticated','public.accepted_sos_photo(uuid)','EXECUTE'),'authenticated clinic actors can invoke the membership-checked photo release RPC');
select extensions.has_column('public','clinics','location_verified_at','SOS clinic pins have an admin verification timestamp');
select extensions.has_column('public','clinics','supports_24h_requested','clinic activation is a request until platform review');
select extensions.ok(position('location_verified_at is not null' in lower(pg_get_functiondef('public.sos_start_round(uuid,integer,integer,integer)'::regprocedure)))>0,'SOS matcher excludes clinics without an admin-verified pin');
select extensions.ok(position('aal2' in lower(pg_get_functiondef('public.admin_review_sos_clinic(uuid,boolean,text)'::regprocedure)))>0,'SOS clinic approval requires step-up admin authentication');
select extensions.has_column('public','web_push_subscriptions','device_id','push subscriptions are addressable per device');
select extensions.has_column('public','sos_requests','closed_at','SOS case closure time is stored for retention');
select extensions.has_column('public','sos_requests','coarse_location','coarse area can replace expired precise location');
select extensions.has_function('public','reduce_closed_sos_locations',ARRAY['integer'],'precise SOS locations have a scheduled reduction function');
select extensions.ok(exists(select 1 from cron.job where jobname='pawcare-sos-round-advance' and schedule='1 second'),'SOS round worker is scheduled at one-second cadence');
select extensions.is(public.reserve_sos_guest_otp('a-phone-hash','a-device-hash','a-ip-hash',1),true,'guest OTP quota admits the first send for phone/device/IP');
select extensions.is(public.reserve_sos_guest_otp('a-phone-hash','a-device-hash','a-ip-hash',1),false,'guest OTP quota rejects repeat sends after the configured cap');
select extensions.is(public.reserve_sos_guest_fallback('fallback-phone-hash','fallback-device-hash','fallback-ip-hash'),true,'provider outage callback fallback admits the first request');

select * from extensions.finish();
rollback;
